const p = $input.first().json;
const text = String(p.text || '').trim();
const m = text.match(/^\/(analyze|pitch|pipeline|help|start|status|followup|note|approve)(?:@\w+)?(?:\s+([\s\S]*))?$/i);
const name = m ? m[1].toLowerCase() : 'help';
const arg = m ? String(m[2] || '').trim() : '';
let command = name === 'start' ? 'help' : name;
let company = '', value = '', action = '';
let valid = !!m;
let reply_text = '';
if (['analyze','pitch','approve'].includes(command)) {
  company = arg;
  if (!company) { command='help'; valid=false; reply_text='Please specify a company, e.g. /analyze MWM, /pitch MWM, or /approve MWM.'; }
} else if (['status','followup','note'].includes(command)) {
  const divider = arg.indexOf('|');
  action = command;
  company = divider>=0 ? arg.slice(0,divider).trim() : '';
  value = divider>=0 ? arg.slice(divider+1).trim() : '';
  command = 'update';
  if (!company || !value) {
    command='help'; valid=false;
    reply_text='Use /status MWM | Contacted, /followup MWM | 2026-11-01, or /note MWM | Met at event.';
  }
} else if (command === 'help' && !m) {
  reply_text = 'Unknown command. Here is the command list:';
}
return [{json:{...p,command,action,company,value,valid,reply_text}}];

