const a=$('Build Personalization Context').first().json;
const raw=String($input.first().json.text||'');
const subject=(raw.match(/^SUBJECT:\s*(.*)$/im)||[])[1]||`Partnership opportunity - ${a.company}`;
const draft=raw.replace(/^SUBJECT:.*
?/im,'').trim();
return [{json:{company_key:a.company_key,company:a.company,subject,draft,created_at:new Date().toISOString(),status:'Draft',chat_id:a.chat_id,reply_text:`Draft for ${a.company}
Subject: ${subject}

${draft}

Saved as draft (not sent). Review it, verify contact_email in Companies, then use /approve ${a.company} to approve and send.`}}];

const q=$('Parse Command').first().json;
const analysed=$('Read Pipeline').all().map(i=>i.json).filter(r=>r.company_key);
const crm=$input.all().map(i=>i.json).filter(r=>r.company_key);
const crmByKey=new Map(crm.map(r=>[String(r.company_key).toLowerCase(),r]));
const analysedKeys=new Set(analysed.map(r=>String(r.company_key).toLowerCase()));
const merged=analysed.map(r=>({...r,...(crmByKey.get(String(r.company_key).toLowerCase())||{})}));
for (const r of crm) if(!analysedKeys.has(String(r.company_key).toLowerCase())) merged.push(r);
const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Paris',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const due=merged.filter(r=>r.next_followup && r.next_followup<=today && !['Declined','Confirmed'].includes(r.status) && r.reminder_sent_for!==r.next_followup);
let reply_text;
if (!merged.length) reply_text='No sponsors in the pipeline yet. Try /analyze MWM.';
else {
 const lines=merged.slice(0,20).map(r=>`- ${r.company}: ${r.score!==undefined&&r.score!==''?r.score+'/100 ('+(r.tier||'')+') · ':''}${r.status||'New'}${r.next_followup?' · follow-up '+r.next_followup:''}`);
 reply_text=`Sponsorship Pipeline (${merged.length}):\n${lines.join('\n')}\n\nFollow-ups due: ${due.length}.\nManage: /status MWM | Contacted or /followup MWM | 2026-11-01`;
}
return [{json:{chat_id:q.chat_id,reply_text}}];

const req = $('Parse Command').first().json;
const companies = $('Read Companies For Update').all().map(x=>x.json).filter(r=>r.company_key);
const existing = $input.all().map(x=>x.json).filter(r=>r.company_key);
const key = String(req.company||'').trim().toLowerCase().replace(/\s+/g,'_');
const company = companies.find(r=>String(r.company_key||'').toLowerCase()===key || String(r.company||'').trim().toLowerCase()===String(req.company||'').trim().toLowerCase());
const failure = msg => [{json:{chat_id:req.chat_id,valid:false,reply_text:msg}}];
if (!company) return failure('Company not found in Companies. Please check its spelling.');
const old = existing.find(r=>String(r.company_key||'').toLowerCase()===String(company.company_key).toLowerCase()) || {};
const statusLabels = {new:'New',researching:'Researching',contacted:'Contacted','in discussion':'In Discussion',negotiating:'Negotiating',confirmed:'Confirmed',declined:'Declined'};
let status = String(old.status||'New');
let next_followup = String(old.next_followup||'');
let notes = String(old.notes||'');
let last_contact_at = String(old.last_contact_at||'');
let reminder_sent_for = String(old.reminder_sent_for||'');
const today = new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Paris',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const value = String(req.value||'').trim();
let info = '';
if (req.action === 'status') {
  const v = statusLabels[value.toLowerCase()];
  if (!v) return failure('Invalid status. Choose New, Researching, Contacted, In Discussion, Negotiating, Confirmed, or Declined.');
  status = v;
  if (['Contacted','In Discussion','Negotiating'].includes(v)) last_contact_at=today;
  info = `Status updated to ${status}`;
} else if (req.action === 'followup') {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return failure('Enter a date as YYYY-MM-DD, for example /followup MWM | 2026-11-01.');
  const date = new Date(`${value}T00:00:00Z`);
  if (Number.isNaN(date.valueOf()) || date.toISOString().slice(0,10)!==value) return failure('Invalid calendar date.');
  next_followup = value;
  reminder_sent_for = '';
  info = `Next follow-up scheduled for ${value}`;
} else if (req.action === 'note') {
  if (value.length>400) return failure('Please keep the note under 400 characters.');
  notes = value;
  info = 'Relationship note saved';
} else return failure('Unsupported update command.');
const updated_at=new Date().toISOString();
return [{json:{valid:true,company_key:company.company_key,company:company.company,status,next_followup,notes,owner_chat_id:req.chat_id,last_contact_at,updated_at,reminder_sent_for,chat_id:req.chat_id,reply_text:`${company.company}: ${info}.\nStatus: ${status}${next_followup?'\nFollow-up: '+next_followup:''}`}}];

const a=$('Select Analysis').first().json;
const org=$('Read Organization Profile').all().map(x=>x.json).find(r=>r.association_name || r.event_name) || {};
const rows=$input.all().map(x=>x.json);
const c=rows.find(r=>String(r.company_key||'').toLowerCase()===String(a.company_key||'').toLowerCase()) || {};
const filled=v=>String(v??'').trim();
return [{json:{...a,association_name:filled(org.association_name)||'[Association name]',sender_name:filled(org.sender_name)||'[Sender name]',sender_role:filled(org.sender_role),sender_email:filled(org.sender_email),event_name:filled(org.event_name)||'AI Builders Hackathon',event_city:filled(org.event_city)||'Paris / Cergy',event_date:filled(org.event_date),event_description:filled(org.event_description)||'Student-led AI product-building hackathon',event_audience:filled(org.event_audience)||'University students interested in AI',event_goals:filled(org.event_goals),expected_attendance:filled(org.expected_attendance),proposed_sponsorship:filled(org.proposed_sponsorship),association_website:filled(org.association_website),tone:filled(org.tone)||'professional and warm',relationship_status:filled(c.status)||'New',relationship_notes:filled(c.notes),next_followup:filled(c.next_followup)}}];

const req = $('Parse Command').first().json;
const key = String(req.company || '').trim().toLowerCase().replace(/\s+/g,'_');
const pick = arr => arr.map(i=>i.json).filter(r=>r && Object.keys(r).length);
const drafts = pick($('Read Draft for Approval').all());
const companies = pick($('Read Company Recipient').all());
const orgs = pick($input.all());
const org = orgs.find(r=>r.approver_telegram_id || r.association_name) || {};
const match = r => String(r.company_key||'').toLowerCase()===key || String(r.company||'').toLowerCase()===String(req.company||'').trim().toLowerCase();
const draft = drafts.find(match);
const co = companies.find(match);
const fail = reason => [{json:{chat_id:req.chat_id,approved:false,reply_text:'Email NOT sent. '+reason}}];
// Closed by default. The owner must explicitly set their numeric Telegram user ID in Organization.
if (!String(org.approver_telegram_id||'').trim()) return fail('Add your Telegram user ID to Organization.approver_telegram_id first.');
if (String(req.user_id)!==String(org.approver_telegram_id).trim()) return fail('You are not authorized to approve emails.');
if (String(req.chat_id)!==String(req.user_id)) return fail('Approvals are allowed only in a private Telegram chat.');
if (!co) return fail('Company not found in Companies.');
if (!draft) return fail('No saved draft. Run /pitch '+req.company+' first.');
if (String(draft.status||'').toLowerCase()==='sent') return fail('This draft has already been sent. Create a new one with /pitch if necessary.');
if (String(draft.status||'').toLowerCase()!=='draft') return fail('Draft status must be Draft. Current status: '+String(draft.status||'(blank)'));
const to = String(co.contact_email||'').trim();
if (!/^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+$/.test(to)) return fail('Provide a valid, verified contact_email in Companies before approving.');
if (!['yes','true','verified','1'].includes(String(co.contact_verified||'').trim().toLowerCase())) return fail('Set Companies.contact_verified to YES after you verify the address.');
const subject=String(draft.subject||'').trim();
const body=String(draft.draft||'').trim();
if (!subject || !body || body.length<60) return fail('The saved email is missing a subject or full body.');
if (/\b(association name|your name|\[sender name\]|\[association name\])\b/i.test(body)) return fail('Your draft still contains placeholders. Edit Drafts or Organization and regenerate it.');
return [{json:{approved:true,chat_id:req.chat_id,user_id:req.user_id,company_key:co.company_key,company:co.company,
 recipient_email:to,subject,draft:body,created_at:draft.created_at||'',
 approved_at:new Date().toISOString(),approved_by:String(req.user_id),
 reply_text:'Approved: '+co.company+'; sending to '+to+'...'}}];

const approved=$('Validate Approval & Recipient').first().json;
return [{json:{chat_id:approved.chat_id,reply_text:
 'Email could not be confirmed as sent to '+approved.recipient_email+'. Check Gmail Sent before retrying. Pipeline status was NOT changed. Error: '+String($input.first().json.error?.message||$input.first().json.message||'Unknown Gmail error')}}];

const a=$('Validate Approval & Recipient').first().json;
const gmail=$input.first().json;
if (!gmail.id) throw new Error('Gmail response contains no message ID. Check Gmail Sent before retrying.');
return [{json:{company_key:a.company_key,company:a.company,subject:a.subject,draft:a.draft,
 created_at:a.created_at,status:'Sent',recipient_email:a.recipient_email,
 approved_at:a.approved_at,approved_by:a.approved_by,
 sent_at:new Date().toISOString(),gmail_message_id:String(gmail.id),chat_id:a.chat_id}}];

const sent=$('Build Sent Draft Record').first().json;
const old=$input.all().map(i=>i.json).find(r=>String(r.company_key||'').toLowerCase()===String(sent.company_key).toLowerCase())||{};
return [{json:{company_key:sent.company_key,company:sent.company,
 status:'Contacted',notes:String(old.notes||''),next_followup:String(old.next_followup||''),
 owner_chat_id:old.owner_chat_id||sent.chat_id,last_contact_at:sent.sent_at,updated_at:new Date().toISOString(),
 reminder_sent_for:String(old.reminder_sent_for||''),
 chat_id:sent.chat_id,recipient_email:sent.recipient_email,gmail_message_id:sent.gmail_message_id}}];

const a=$('Build Contacted Update').first().json;
return [{json:{chat_id:a.chat_id,reply_text:
 'Email sent via Gmail to '+a.recipient_email+' for '+a.company+'.
Draft status: Sent.
Pipeline status: Contacted.
Gmail message ID: '+a.gmail_message_id}}];
